@startuml

class Department {}

class Room {}

class Bed {
  + Category : StayCategory
}

class Category {
  + Price : double
}

enum StayCategory {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class Stay {
  + StartDate : date
  + Status : string
}

class Registration {
  + IdentificationData : string
  + AssessmentResults : string
  + RegistrationDate : date
}

class Assessment {
  + Needs : string
  + ValidatedType : StayCategory
}

class WaitingListPosition {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Decision : string
  + IsValidated : boolean
}

class Invoice {
  + OutstandingAmount : double
  + Status : string
  + Date : date
}

class CreditNote {
  + Amount : double
}

class Payment {
  + Amount : double
  + Date : datetime
}

Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Inhabitant "1" -- "*" Stay
Stay "1" -- "1" Category
Inhabitant "1" -- "0..1" Registration
Registration "1" -- "0..1" Assessment
Inhabitant "1" -- "0..*" WaitingListPosition
WaitingListPosition "0..*" -- "1" StayCategory
Inhabitant "1" -- "0..*" Proposal
Proposal "0..*" -- "1" StayCategory
Inhabitant "1" -- "0..*" Invoice
Invoice "1" -- "0..*" Payment
Invoice "1" -- "0..1" CreditNote

@enduml

